/** lamp post: a 0.3 m plinth block, a POLE_W pole to the top (the lamp arm above 4 m is visual: over every head) */
export const LAMP_PLINTH = 0.3, LAMP_POLE = 0.16;
export interface PropSpec { k: PropKind; u: number; v: number; y?: number; rot?: boolean; s?: number; seed?: number; col?: string; /** consoles: the side the monitor bridge stands on */ back?: Side; /** consoles: all bridge, no desk strip (a display tower) */ tower?: boolean; /** desks / consoles: the side the operator sits on (the monitors face it) */ face?: Side; /** tables: a glowing map top */ holo?: boolean }
const Pr = (k: PropKind, u: number, v: number, o: Partial<PropSpec> = {}): PropSpec => ({ k, u, v, ...o });
/** a designed yard cover cluster: barrier + big crate with a crate on top + two barrels, every piece touching
 *  (no capsule slots); `rot` turns it 90° */
function coverCluster(u: number, v: number, rot: boolean): PropSpec[] {
  const P = (a: number, b: number): [number, number] => rot ? [u + b, v + a] : [u + a, v + b];
  const out: PropSpec[] = [];
  const add = (k: PropKind, a: number, b: number, o: Partial<PropSpec> = {}) => { const [pu, pv] = P(a, b); out.push(Pr(k, pu, pv, { rot, ...o })); };
  add("barrier", 0, 0); add("crateL", 2.3, 0.1); add("crate", 2.3, 0.1, { y: G + 1.1, rot: !rot });
  add("barrel", -1.95, 0.31); add("barrel", -1.95, -0.31);
  return out;
}

