// ------------------------------------------------------------------------------------------------ loot
/** designed loot (LOOT_SPOTS): chests in every building, on the roofs and on the dish platform (the
 *  landmark); floor loot along the lanes, decks and bridges. World metres, y = the floor the loot stands on. */
export const LOOT_SPOTS: { chests: [number, number, number, number][]; floor: [number, number, number][] } = (() => {
  const W = (u: number, y: number, v: number): [number, number, number] => [CX + u, y, CZ + v];
  const C = (u: number, y: number, v: number, yaw: number): [number, number, number, number] => [CX + u, y, CZ + v, yaw];
  const chests: [number, number, number, number][] = [
    C(17.6, F0, 5.9, Math.PI), C(26.8, F0, -2.8, -Math.PI / 2),          // server hall + UPS room
    C(21.0, L2, 1.2, -Math.PI / 2),                                      // control room
    C(36.8, L2, 0.1, Math.PI), C(44.8, L2, -7.8, 0),                    // labs 1 + 2
    C(-8.95, L2, -12.2, -Math.PI / 2),                                  // bunks
    C(17.8, F0, -25.2, 0),                                      // garage
    C(48.8, F0, -28.9, 0),                                               // dish equipment room
    C(48.5, 43.0, -28.9, 0),                                             // THE DISH PLATFORM (landmark)
    C(-28.2, F0, 27.1, Math.PI / 2),                                      // gate booth
    C(15.6, 41.9, 3.6, Math.PI),                                         // control-room roof (solar deck)
    C(9, 35.6, 24.4, Math.PI),                                           // helipad
    C(19.6, 45.0, -3.4, 0),                                              // the observation pod's roof (3rd level)
  ];
  const floor: [number, number, number][] = [
    W(8.2, F0, 3.6), W(17.2, F0, -4.2), W(24.2, F0, 3.8), W(16.8, L2, 5.7), W(-3, L2, -5.3), W(29, L2, -2.5), W(42.1, L2, -14.5),
    W(32.2, L2, -6.8), W(40.1, L2, -2.4), W(-13.8, L2, -6.4), W(-14.6, L2, -2.8), W(13.5, F0, -18.5), W(44.5, F0, -22.4), W(43.6, L2, -21.4),
    W(9, 35.6, 12), W(-24, G, 30.5), W(-14, G, 18), W(46, G, 20), W(-36, G, -14), W(26.8, L2, -3.6), W(14.9, L2, -12), W(0.8, G, -16.6),
    W(43.5, 41.9, -2), W(-16, 41.7, -9), W(17, L2, -4.9),
  ];
  // rooms: the kit's slots replace the designed ones on room floors; the designed ones elsewhere stay (roofs, decks, landmark)
  const out = { chests: chests.filter((c) => !inRoom(c[0], c[1], c[2])), floor: floor.filter((f) => !inRoom(f[0], f[1], f[2])) };
  const all = [...out.chests.map((c) => [c[0], c[1], c[2]]), ...out.floor];
  const free = (p: number[]) => { const ok = !all.some((q) => Math.abs(q[1] - p[1]) < 1.5 && dmath.hypot(q[0] - p[0], q[2] - p[2]) < 1.5); if (ok) all.push(p); return ok; };
  return { chests: [...out.chests, ...INTERIOR_LOOT.chests.filter((c) => free(c)), ...HOT_CHEST_SLOTS.filter((c) => free(c))], floor: [...out.floor, ...SURFACE_LOOT.filter((f) => free(f)), ...INTERIOR_LOOT.floor.filter((f) => free(f))] };
})();

